window.NET_CONTENT={"units":[{"id":"u1","label":"Unit 1","title":"Emergence of Psychology","description":"Academic psychology in India, psychological thought, Eastern psychology, and science and spirituality.","topics":[["u1t1","Academic Psychology in India"],["u1t2","Psychological Thought"],["u1t3","Eastern Psychology"],["u1t4","Science and Spirituality"]]},{"id":"u2","label":"Unit 2","title":"Research Methodology and Statistics","description":"Research methodology, paradigms of research, statistics, and experimental designs.","topics":[["u2t1","Research Methodology"],["u2t2","Paradigms of Research"],["u2t3","Statistics"],["u2t4","Experimental Designs"]]},{"id":"u3","label":"Unit 3","title":"Psychological Testing","description":"History, types, construction, standardization, areas of testing, attitude scales, and applications.","topics":[["u3t1","History and Types of Tests"],["u3t2","Test Construction and Standardization"],["u3t3","Areas of Testing"],["u3t4","Attitude Scales and Applications"]]},{"id":"u4","label":"Unit 4","title":"Biological Basis of Behavior","description":"Biopsychology, sensory systems, neurons and brain, physiological methods, motivation, emotion, and genetics.","topics":[["u4t1","Biopsychology and Physiological Psychology"],["u4t2","Sensory Systems"],["u4t3","Neurons and Brain"],["u4t4","Methods and Biological Bases of Behavior"],["u4t5","Genetics and Behavior"]]},{"id":"u5","label":"Unit 5","title":"Attention, Perception, Learning, Memory and Forgetting","description":"Attention, perception, illusion, learning processes, memory, and forgetting.","topics":[["u5t1","Attention"],["u5t2","Perception and Illusion"],["u5t3","Learning Processes"],["u5t4","Memory and Forgetting"]]},{"id":"u6","label":"Unit 6","title":"Thinking, Intelligence, and Creativity","description":"Thought processes, concepts, reasoning, problem solving, decision-making, metacognition, intelligence, and creativity.","topics":[["u6t1","Thought and Concepts"],["u6t2","Reasoning, Problem Solving and Decision Making"],["u6t3","Metacognition"],["u6t4","Intelligence"],["u6t5","Creativity"]]},{"id":"u7","label":"Unit 7","title":"Personality, Motivation, Emotion, Stress and Coping","description":"Personality theories, motivation, emotion, conflicts, stress, and coping.","topics":[["u7t1","Personality"],["u7t2","Motivation"],["u7t3","Emotion"],["u7t4","Conflicts"],["u7t5","Stress and Coping"]]},{"id":"u8","label":"Unit 8","title":"Social Psychology","description":"Nature and scope, theoretical perspectives, social perception, influence, groups, intergroup relations, and applications.","topics":[["u8t1","Nature, Scope and History"],["u8t2","Theoretical Perspectives"],["u8t3","Social Perception and Attitudes"],["u8t4","Social Influence and Groups"],["u8t5","Intergroup Relations"],["u8t6","Applied Social Psychology"]]},{"id":"u9","label":"Unit 9","title":"Human Development and Interventions","description":"Developmental processes and theories, psychopathology, psychotherapy, educational applications, guidance, and counselling.","topics":[["u9t1","Developmental Processes and Theories"],["u9t2","Development Across Domains"],["u9t3","Psychopathology"],["u9t4","Psychotherapies"],["u9t5","Educational Applications"],["u9t6","Guidance and Counselling"]]},{"id":"u10","label":"Unit 10","title":"Emerging Areas","description":"Social issues, gender, poverty, disability and migration, peace psychology, wellbeing, health, and psychology-technology interface.","topics":[["u10t1","Social Issues and Role of Psychology"],["u10t2","Gender, Poverty, Disability and Migration"],["u10t3","Peace Psychology"],["u10t4","Wellbeing and Self-Growth"],["u10t5","Health"],["u10t6","Psychology and Technology Interface"]]}],"microtopics":[{"id":"m001","topic":"u1t1","title":"Scientific psychology: goals","description":"Scientific psychology uses systematic methods to study behavior and mental processes.","quick":"Scientific psychology uses systematic methods to study behavior and mental processes.","core":"The supplied Self-Teaching Guide frames four explicit goals: describe, explain, predict, and control behavior.","retrieve":"Which four goals are highlighted for scientific psychology?","answer":"Describe, explain, predict, and control behavior.","applyQ":"A researcher first records a pattern, then proposes why it occurs, forecasts when it may occur, and designs an intervention. Which sequence of goals is represented?","options":["Describe → explain → predict → control","Measure → diagnose → prescribe → treat","Observe → remember → forget → generalize"],"correct":0,"applyWhy":"The sequence matches the four goals identified in the supplied source."},{"id":"m002","topic":"u1t2","title":"Major schools of psychology","description":"Early schools differed in what they treated as psychology’s proper subject matter.","quick":"Early schools differed in what they treated as psychology’s proper subject matter.","core":"The supplied sources contrast structuralism, functionalism, Gestalt psychology, psychoanalysis, behaviorism and later humanistic and cognitive approaches.","retrieve":"Which approach is most directly associated with observable behavior as its primary focus?","answer":"Behaviorism.","applyQ":"A psychologist deliberately limits explanations to observable responses and environmental conditions. Which school is most closely represented?","options":["Behaviorism","Structuralism","Gestalt psychology"],"correct":0,"applyWhy":"The emphasis on observable behavior is characteristic of behaviorism."},{"id":"m003","topic":"u1t2","title":"Cognitive revolution","description":"The cognitive revolution brought mental processes back into central psychological explanation.","quick":"The cognitive revolution brought mental processes back into central psychological explanation.","core":"Baron and Misra describe a shift from a strict behavior-focused paradigm toward studying mind as information processing, followed by representational and connectionist approaches.","retrieve":"What broad change is associated with the cognitive revolution?","answer":"A renewed scientific study of mental processes.","applyQ":"A researcher studies attention, memory and thinking using information-processing models. Which broad development does this reflect?","options":["Cognitive revolution","Classical conditioning","Psychometric standardization"],"correct":0,"applyWhy":"Attention, memory and thinking are central examples of cognitive processes."},{"id":"m004","topic":"u1t3","title":"Indian psychology and the person","description":"The supplied Indian psychology material presents the person and consciousness as important units of analysis.","quick":"The supplied Indian psychology material presents the person and consciousness as important units of analysis.","core":"Baron and Misra summarize a classical Indian perspective in which psychology studies the person (Jiva), with consciousness treated as distinct from material objects including brain and mind.","retrieve":"What term is used in the cited classical Indian perspective for the person?","answer":"Jiva.","applyQ":"A course describes psychology as the study of the person rather than only isolated behavior. Which term from the source fits?","options":["Jiva","Synapse","Norm"],"correct":0,"applyWhy":"The cited classical Indian formulation uses Jiva for the person."},{"id":"m005","topic":"u1t4","title":"Knowledge paradigms: ontology, epistemology, methodology","description":"Questions about what exists, how knowledge is justified, and how it is studied belong to different levels of a knowledge paradigm.","quick":"Questions about what exists, how knowledge is justified, and how it is studied belong to different levels of a knowledge paradigm.","core":"The supplied NET source groups ontology, epistemology and methodology as essential aspects of knowledge paradigms.","retrieve":"Name the three components emphasized in the source.","answer":"Ontology, epistemology, and methodology.","applyQ":"A researcher separately asks what reality is, how it can be known, and which procedures should be used. What framework is being applied?","options":["Ontology, epistemology, methodology","Reliability, validity, norms","Stimulus, response, reinforcement"],"correct":0,"applyWhy":"These three terms map directly onto the three questions in the scenario."},{"id":"m006","topic":"u2t1","title":"Scientific method and hypothesis","description":"A hypothesis gives a research project a testable expectation.","quick":"A hypothesis gives a research project a testable expectation.","core":"The Self-Teaching Guide identifies forming a hypothesis as an important step in the scientific method and distinguishes research methods used to gather data.","retrieve":"What role does a hypothesis play in scientific research?","answer":"It provides a testable expectation about a relationship or outcome.","applyQ":"A researcher predicts that sleep duration will be associated with memory performance and then collects data. What is the prediction?","options":["A hypothesis","A norm","A sampling frame"],"correct":0,"applyWhy":"A testable prediction about variables is a hypothesis."},{"id":"m007","topic":"u2t1","title":"Naturalistic observation","description":"Naturalistic observation records behavior in a setting without imposing an experimental treatment.","quick":"Naturalistic observation records behavior in a setting without imposing an experimental treatment.","core":"The supplied Self-Teaching Guide distinguishes naturalistic observation from experimental methods and notes that naturalistic observation does not use a control group.","retrieve":"Does naturalistic observation require a control group?","answer":"No.","applyQ":"A psychologist observes children on a playground without assigning conditions or manipulating variables. Which method is this?","options":["Naturalistic observation","Laboratory experiment","Randomized trial"],"correct":0,"applyWhy":"The defining feature here is observation in a natural setting without experimental manipulation."},{"id":"m008","topic":"u2t1","title":"Independent and dependent variables","description":"Experiments distinguish manipulated variables from measured outcomes.","quick":"Experiments distinguish manipulated variables from measured outcomes.","core":"The Self-Teaching Guide identifies the independent variable as the variable assigned or manipulated by the experimenter and the dependent variable as the measured outcome.","retrieve":"Which variable is assigned or manipulated by the experimenter?","answer":"The independent variable.","applyQ":"A researcher assigns participants to two study schedules and measures test scores. Which is the independent variable?","options":["Study schedule","Test score","Population"],"correct":0,"applyWhy":"The study schedule is the manipulated condition."},{"id":"m009","topic":"u2t2","title":"Research paradigms","description":"A research paradigm provides assumptions about knowledge and inquiry.","quick":"A research paradigm provides assumptions about knowledge and inquiry.","core":"The supplied NET source includes positivism, post-positivism, critical perspective, social constructionism, existential phenomenology and cooperative enquiry, along with Indian paradigms.","retrieve":"Which paradigm is explicitly listed in the supplied NET outline?","answer":"Social constructionism.","applyQ":"A researcher examines how meanings are produced through social interaction and language. Which listed paradigm is especially relevant?","options":["Social constructionism","Classical conditioning","Trait theory"],"correct":0,"applyWhy":"The supplied outline explicitly includes social constructionism."},{"id":"m010","topic":"u2t3","title":"Correlation","description":"Correlation describes the direction and degree of association between variables.","quick":"Correlation describes the direction and degree of association between variables.","core":"The Self-Teaching Guide uses positive, negative and zero correlation as basic ways to describe covariance and association.","retrieve":"If two variables increase together, what type of correlation is suggested?","answer":"Positive correlation.","applyQ":"As study time increases, test scores tend to increase in a sample. What association is suggested?","options":["Positive correlation","Negative correlation","Zero correlation"],"correct":0,"applyWhy":"Both variables move in the same direction."},{"id":"m011","topic":"u2t4","title":"Experimental control","description":"Experimental control helps researchers isolate the effect of a manipulated variable.","quick":"Experimental control helps researchers isolate the effect of a manipulated variable.","core":"The supplied material emphasizes the experiment as a method that gives the researcher control over variables and distinguishes a control group from a treatment group.","retrieve":"Why is experimental control important?","answer":"It helps isolate the effects of the manipulated variable.","applyQ":"Two groups are treated alike except for one experimental condition. What is the purpose?","options":["To isolate the treatment effect","To eliminate measurement entirely","To replace the hypothesis"],"correct":0,"applyWhy":"Keeping other conditions comparable strengthens causal inference."},{"id":"m012","topic":"u3t1","title":"History and definition of psychological testing","description":"Psychological testing involves standardized procedures for sampling behavior to make inferences about attributes.","quick":"Psychological testing involves standardized procedures for sampling behavior to make inferences about attributes.","core":"The PowerWithin outline includes the history of psychological testing and distinguishes tests, assessments, measurements and surveys.","retrieve":"What process is central to psychological testing?","answer":"Administering, scoring and interpreting psychological tests.","applyQ":"A standardized instrument is administered, scored and interpreted to infer an attribute. What activity is being described?","options":["Psychological testing","Naturalistic observation","Free association"],"correct":0,"applyWhy":"This matches the supplied definition of psychological testing."},{"id":"m013","topic":"u3t2","title":"Test construction: item writing and analysis","description":"Good tests require carefully written items and systematic evaluation of those items.","quick":"Good tests require carefully written items and systematic evaluation of those items.","core":"The NET source places item writing and item analysis within test construction before standardization.","retrieve":"Which two activities are explicitly listed under test construction?","answer":"Item writing and item analysis.","applyQ":"A test developer reviews whether individual questions function appropriately before finalizing a scale. Which area is involved?","options":["Item analysis","Random assignment","Dream analysis"],"correct":0,"applyWhy":"Evaluating individual items is item analysis."},{"id":"m014","topic":"u3t2","title":"Reliability, validity and norms","description":"Psychometric quality concerns consistency, interpretation and reference standards.","quick":"Psychometric quality concerns consistency, interpretation and reference standards.","core":"The supplied NET source groups reliability, validity and norms under test standardization.","retrieve":"Which trio belongs to test standardization in the source?","answer":"Reliability, validity and norms.","applyQ":"A test gives consistent scores but its scores do not support the intended interpretation. Which issue needs closer examination?","options":["Validity","Reliability alone","Sampling only"],"correct":0,"applyWhy":"Consistency and validity are distinct; intended interpretation concerns validity."},{"id":"m015","topic":"u3t3","title":"Intelligence and aptitude testing","description":"Psychological testing includes cognitive abilities, aptitude and intelligence among its major application areas.","quick":"Psychological testing includes cognitive abilities, aptitude and intelligence among its major application areas.","core":"The supplied NET outline identifies intelligence and aptitude among areas of testing and also includes creativity and neuropsychological testing.","retrieve":"Which is an area of psychological testing named in the source?","answer":"Aptitude.","applyQ":"An assessment estimates a person’s potential to learn a particular skill. Which area is most relevant?","options":["Aptitude testing","Attitude scaling","Crowding"],"correct":0,"applyWhy":"Aptitude concerns potential or capacity relevant to learning or performance."},{"id":"m016","topic":"u3t4","title":"Likert and semantic differential scales","description":"Attitude measurement can use structured rating formats.","quick":"Attitude measurement can use structured rating formats.","core":"The supplied NET outline includes Semantic Differential, Stapel and Likert scales under attitude scales.","retrieve":"Which is explicitly named as an attitude scale format?","answer":"Likert scale.","applyQ":"Respondents indicate their level of agreement with a series of statements. Which format fits best?","options":["Likert scale","Naturalistic observation","Sociogram"],"correct":0,"applyWhy":"Agreement ratings are characteristic of Likert-type scales."},{"id":"m017","topic":"u4t1","title":"Biopsychology","description":"Biopsychology studies the biological bases of behavior.","quick":"Biopsychology studies the biological bases of behavior.","core":"The supplied NET source describes biopsychology as a field concerned with the physiology/biology of behavior and lists physiological psychology, psychobiology and behavioral neuroscience as related labels.","retrieve":"What does biopsychology primarily study?","answer":"The biological basis of behavior.","applyQ":"A researcher investigates how neural activity relates to behavior. Which broad field is being used?","options":["Biopsychology","Psychometrics","Social constructionism"],"correct":0,"applyWhy":"The research question directly concerns biological mechanisms of behavior."},{"id":"m018","topic":"u4t2","title":"Sensory receptors and sensation","description":"Sensory systems begin with receptors that respond to physical stimulation.","quick":"Sensory systems begin with receptors that respond to physical stimulation.","core":"The Unit 4 outline covers general and specific sensations, receptors and sensory processes.","retrieve":"What role do sensory receptors play?","answer":"They detect specific forms of stimulation.","applyQ":"A specialized receptor responds to a particular type of physical energy. What process is being described?","options":["Sensory reception","Norming","Extinction"],"correct":0,"applyWhy":"Receptors transduce or detect particular forms of stimulation."},{"id":"m019","topic":"u4t3","title":"Neuron structure and neural impulse","description":"Neurons are specialized cells that communicate information through electrical and chemical processes.","quick":"Neurons are specialized cells that communicate information through electrical and chemical processes.","core":"The NET outline includes neuron structure, functions, types and neural impulse.","retrieve":"What is a neuron?","answer":"A specialized cell involved in nervous-system communication.","applyQ":"A cell receives information and transmits a neural signal to other cells. What is it?","options":["Neuron","Endocrine gland","Psychological test"],"correct":0,"applyWhy":"Neurons are the basic communicating cells of the nervous system."},{"id":"m020","topic":"u4t3","title":"Synaptic transmission and neurotransmitters","description":"Neurons communicate at synapses using chemical messengers as well as electrical activity.","quick":"Neurons communicate at synapses using chemical messengers as well as electrical activity.","core":"The source specifically lists synaptic transmission and neurotransmitters under Unit 4.","retrieve":"What term describes communication across a synapse?","answer":"Synaptic transmission.","applyQ":"A chemical messenger released from one neuron affects the next cell. Which concept is involved?","options":["Neurotransmitter-mediated synaptic transmission","Norm referencing","Classical extinction"],"correct":0,"applyWhy":"Neurotransmitters participate in chemical communication across synapses."},{"id":"m021","topic":"u4t5","title":"Nature and nurture","description":"Behavior reflects interaction between biological inheritance and environmental experience.","quick":"Behavior reflects interaction between biological inheritance and environmental experience.","core":"The supplied Unit 4 outline includes chromosomal anomalies and the nature–nurture controversy, including twin and adoption studies.","retrieve":"Which designs are explicitly associated with the nature–nurture discussion in the source?","answer":"Twin and adoption studies.","applyQ":"Researchers compare twins and adopted individuals to separate hereditary and environmental influences. What issue is being studied?","options":["Nature–nurture","Attitude scaling","Social loafing"],"correct":0,"applyWhy":"Twin and adoption studies are classic ways to examine hereditary and environmental contributions."},{"id":"m022","topic":"u5t1","title":"Selective attention","description":"Attention involves selecting some information for enhanced processing.","quick":"Attention involves selecting some information for enhanced processing.","core":"The supplied NET unit begins with attention, while Ciccarelli/White places attention within the broader study of sensation, perception and cognition.","retrieve":"What is selective attention?","answer":"Focusing processing on some information while reducing processing of other information.","applyQ":"In a noisy room, a student concentrates on one conversation while ignoring most background talk. What is illustrated?","options":["Selective attention","Retroactive interference","Projection"],"correct":0,"applyWhy":"The learner selects one information stream for focused processing."},{"id":"m023","topic":"u5t2","title":"Perceptual organization","description":"Perception involves organizing and interpreting sensory information.","quick":"Perception involves organizing and interpreting sensory information.","core":"The sources distinguish sensation from perception and include Gestalt principles as an important way of understanding organized experience.","retrieve":"What does perception add to raw sensory input?","answer":"Organization and interpretation.","applyQ":"Two people receive similar sensory input but organize it differently because of context. Which process is central?","options":["Perception","Synaptic transmission","Norming"],"correct":0,"applyWhy":"Perception involves interpretation and organization of sensory information."},{"id":"m024","topic":"u5t2","title":"Illusions","description":"An illusion is a misperception of a real external stimulus.","quick":"An illusion is a misperception of a real external stimulus.","core":"The NET Unit 5 outline explicitly includes illusion within perception.","retrieve":"What distinguishes an illusion from a hallucination?","answer":"An illusion involves a real external stimulus that is misperceived.","applyQ":"A straight line is seen as bent because of surrounding visual context. Which phenomenon fits?","options":["Illusion","Hallucination","Amnesia"],"correct":0,"applyWhy":"There is a real stimulus, but it is interpreted incorrectly."},{"id":"m025","topic":"u5t3","title":"Classical conditioning","description":"Classical conditioning is learning through associations between stimuli.","quick":"Classical conditioning is learning through associations between stimuli.","core":"Ciccarelli/White identifies Pavlovian conditioning and applies it to phobias, taste aversions and drug dependency; the NET outline includes learning processes.","retrieve":"What happens to a neutral stimulus through classical conditioning?","answer":"It can acquire the ability to elicit a learned response.","applyQ":"A clinic becomes anxiety-provoking after repeated pairing with painful treatment. What learning process is illustrated?","options":["Classical conditioning","Operant conditioning","Insight learning"],"correct":0,"applyWhy":"The clinic acquires an eliciting function through association."},{"id":"m026","topic":"u5t3","title":"Operant conditioning and reinforcement","description":"Operant conditioning links behavior with its consequences.","quick":"Operant conditioning links behavior with its consequences.","core":"Ciccarelli/White distinguishes positive and negative reinforcement, punishment, schedules of reinforcement, extinction and stimulus control.","retrieve":"What is reinforcement intended to do?","answer":"Increase the future probability of a behavior.","applyQ":"A student receives praise after completing practice questions and completes more questions later. What consequence is operating?","options":["Reinforcement","Punishment","Extinction"],"correct":0,"applyWhy":"A consequence that increases future behavior is reinforcement."},{"id":"m027","topic":"u5t3","title":"Observational learning","description":"People can learn by observing models rather than only through direct reinforcement.","quick":"People can learn by observing models rather than only through direct reinforcement.","core":"Ciccarelli/White identifies observational learning and its four elements within the learning chapter.","retrieve":"What is observational learning?","answer":"Learning that occurs through observing another person or model.","applyQ":"A child learns a new action after watching an older sibling perform it. What learning process is illustrated?","options":["Observational learning","Classical extinction","Retrograde amnesia"],"correct":0,"applyWhy":"The behavior is acquired through observation of a model."},{"id":"m028","topic":"u5t4","title":"Memory systems","description":"Memory involves encoding, storage and retrieval of information.","quick":"Memory involves encoding, storage and retrieval of information.","core":"Ciccarelli/White organizes memory around sensory memory, short-term/working memory and long-term memory and emphasizes the stages of putting information in, keeping it and getting it out.","retrieve":"Which three broad processes are central to memory?","answer":"Encoding, storage, and retrieval.","applyQ":"A learner takes information in, retains it, and later brings it back to mind. Which sequence is this?","options":["Encoding → storage → retrieval","Stimulus → response → punishment","Sensation → receptor → hormone"],"correct":0,"applyWhy":"These are the standard memory processes highlighted in the source."},{"id":"m029","topic":"u5t4","title":"Forgetting and interference","description":"Forgetting can arise from interference, retrieval problems and other factors.","quick":"Forgetting can arise from interference, retrieval problems and other factors.","core":"The supplied memory material distinguishes forms of amnesia and describes how new and old information can be affected.","retrieve":"What is anterograde amnesia?","answer":"Difficulty forming new long-term memories after an event or injury.","applyQ":"After a brain injury, a person can discuss old events but cannot reliably form new memories. Which pattern fits?","options":["Anterograde amnesia","Retrograde amnesia","Selective attention"],"correct":0,"applyWhy":"The difficulty is specifically with forming new memories."},{"id":"m030","topic":"u6t1","title":"Associationism and Gestalt perspectives","description":"Different theories explain thought by emphasizing associations or organized wholes.","quick":"Different theories explain thought by emphasizing associations or organized wholes.","core":"The PowerWithin Unit 6 material includes associationism and Gestalt perspectives and describes laws of association and organized patterns.","retrieve":"What is a central Gestalt claim?","answer":"The whole is more than the sum of its parts.","applyQ":"A learner suddenly reorganizes a problem and sees the relationship among its parts as a whole. Which perspective fits?","options":["Gestalt","Behaviorism","Psychometric theory"],"correct":0,"applyWhy":"Gestalt emphasizes organized wholes and restructuring of experience."},{"id":"m031","topic":"u6t1","title":"Concept formation","description":"Concepts organize objects, events or ideas into meaningful categories.","quick":"Concepts organize objects, events or ideas into meaningful categories.","core":"The NET outline includes rules, types and strategies of concept formation and the role of concepts in thinking.","retrieve":"What is the basic function of a concept?","answer":"To organize related instances into a category or mental representation.","applyQ":"A student groups different examples under the category “reinforcer” despite their different physical forms. What process is involved?","options":["Concept formation","Synaptic transmission","Norming"],"correct":0,"applyWhy":"The student is organizing varied instances under a common category."},{"id":"m032","topic":"u6t2","title":"Reasoning","description":"Reasoning involves drawing conclusions from information or premises.","quick":"Reasoning involves drawing conclusions from information or premises.","core":"The NET outline includes types of reasoning within Unit 6.","retrieve":"What does reasoning involve?","answer":"Using information or premises to reach a conclusion.","applyQ":"A learner uses a general rule and a specific case to reach a conclusion. Which process is involved?","options":["Reasoning","Classical conditioning","Attitude scaling"],"correct":0,"applyWhy":"The learner is deriving a conclusion from available information."},{"id":"m033","topic":"u6t2","title":"Problem solving and obstacles","description":"Problem solving requires moving from a current state toward a goal.","quick":"Problem solving requires moving from a current state toward a goal.","core":"The source includes problem types, strategies and obstacles and separates problem solving from decision making.","retrieve":"What makes a situation a problem?","answer":"A goal exists but the route to the goal is not immediately available.","applyQ":"A student knows the desired result but cannot see how to reach it and tries several strategies. What process is central?","options":["Problem solving","Simple recall","Psychological testing"],"correct":0,"applyWhy":"The central feature is a goal with an initially unavailable route."},{"id":"m034","topic":"u6t3","title":"Metacognition","description":"Metacognition is thinking about and regulating one’s own cognitive processes.","quick":"Metacognition is thinking about and regulating one’s own cognitive processes.","core":"The NET outline separates metacognitive knowledge and metacognitive regulation.","retrieve":"What is metacognition?","answer":"Knowledge and regulation of one’s own cognitive processes.","applyQ":"A student notices that rereading is not helping and changes strategy to self-testing. What is this an example of?","options":["Metacognitive regulation","Classical conditioning","Social loafing"],"correct":0,"applyWhy":"The student monitors cognition and changes strategy accordingly."},{"id":"m035","topic":"u6t4","title":"Intelligence theories","description":"Psychologists have proposed multiple models of intelligence.","quick":"Psychologists have proposed multiple models of intelligence.","core":"The supplied Unit 6 outline includes Spearman, Thurstone, Jensen, Cattell, Gardner, Sternberg, Goleman, and Das, Kar & Parrila.","retrieve":"Which theorist is associated with the g factor?","answer":"Charles Spearman.","applyQ":"A theory proposes a general factor contributing to performance across different cognitive tasks. Whose model is most directly represented?","options":["Spearman","Guilford","Torrance"],"correct":0,"applyWhy":"Spearman proposed a general intelligence factor, g."},{"id":"m036","topic":"u6t5","title":"Creativity","description":"Creativity concerns producing ideas or products that involve novelty and usefulness or appropriateness.","quick":"Creativity concerns producing ideas or products that involve novelty and usefulness or appropriateness.","core":"The Unit 6 material includes Torrance, Getzels & Jackson, Guilford, Wallach & Kogan and the relationship between intelligence and creativity; Mednick is also discussed in the supplied source.","retrieve":"Which pair is explicitly included in the NET creativity outline?","answer":"Guilford and Torrance.","applyQ":"A researcher measures divergent production and creative responses in students. Which Unit 6 area is being assessed?","options":["Creativity","Classical conditioning","Norms"],"correct":0,"applyWhy":"Divergent production and creative responses belong to the creativity area."},{"id":"m037","topic":"u7t1","title":"Personality: determinants and approaches","description":"Personality concerns relatively enduring patterns and individual differences.","quick":"Personality concerns relatively enduring patterns and individual differences.","core":"The NET outline includes biological and sociocultural determinants and psychoanalytic, neo-Freudian, social-learning, trait, cognitive, humanistic, existential and transpersonal approaches.","retrieve":"Which is an approach to personality listed in the source?","answer":"Trait approach.","applyQ":"A researcher explains stable individual differences using dimensions that vary across people. Which approach is this?","options":["Trait approach","Behavioral economics","Psychophysics"],"correct":0,"applyWhy":"Trait approaches describe relatively enduring dimensions of individual differences."},{"id":"m038","topic":"u7t1","title":"Locus of control","description":"Locus of control concerns beliefs about where control over outcomes resides.","quick":"Locus of control concerns beliefs about where control over outcomes resides.","core":"The Unit 7 outline explicitly includes Rotter’s locus of control.","retrieve":"Which theorist is associated with locus of control in the supplied outline?","answer":"Julian Rotter.","applyQ":"A person generally believes outcomes depend mainly on their own actions. Which construct is relevant?","options":["Locus of control","Conditioned stimulus","Normative influence"],"correct":0,"applyWhy":"The scenario concerns beliefs about personal control over outcomes."},{"id":"m039","topic":"u7t2","title":"Motivational cycle","description":"Motivation can be described as a process linking needs, drives, behavior and outcomes.","quick":"Motivation can be described as a process linking needs, drives, behavior and outcomes.","core":"The NET outline includes instincts, needs, drives, arousal, incentives and the motivational cycle.","retrieve":"Which concept is explicitly part of the motivational cycle material?","answer":"Drive.","applyQ":"A state of internal tension energizes behavior toward a goal. Which motivational concept fits?","options":["Drive","Norm","Illusion"],"correct":0,"applyWhy":"Drive refers to an energizing state associated with a need."},{"id":"m040","topic":"u7t2","title":"Achievement, affiliation and power","description":"Human motivation can include needs for achievement, affiliation and power.","quick":"Human motivation can include needs for achievement, affiliation and power.","core":"The supplied Unit 7 outline explicitly lists achievement, affiliation and power.","retrieve":"Name one of the three motives listed.","answer":"Achievement.","applyQ":"A student is strongly motivated by meeting challenging standards of performance. Which motive is especially relevant?","options":["Achievement","Affiliation","Territoriality"],"correct":0,"applyWhy":"Concern with challenging standards and accomplishment is achievement motivation."},{"id":"m041","topic":"u7t3","title":"Theories of emotion","description":"Emotion theories differ in how physiological arousal, appraisal and subjective experience are related.","quick":"Emotion theories differ in how physiological arousal, appraisal and subjective experience are related.","core":"The NET outline includes James–Lange, Cannon–Bard, Schachter–Singer and Lazarus among theories of emotion.","retrieve":"Which theory links emotion to physiological changes following perception of a stimulus?","answer":"James–Lange theory.","applyQ":"A theory proposes that bodily changes contribute to the experience of emotion rather than merely following it. Which theory is being referenced?","options":["James–Lange","Trait theory","Social identity theory"],"correct":0,"applyWhy":"James–Lange places bodily responses before the conscious emotional experience."},{"id":"m042","topic":"u7t4","title":"Conflict types","description":"Conflict occurs when competing goals or action tendencies create incompatible choices.","quick":"Conflict occurs when competing goals or action tendencies create incompatible choices.","core":"The Self-Teaching Guide includes approach-approach, approach-avoidance, double approach-avoidance and avoidance-avoidance conflicts.","retrieve":"Which conflict involves choosing between two undesirable alternatives?","answer":"Avoidance-avoidance conflict.","applyQ":"A person must choose between two unpleasant options and wants to escape both. What type is this?","options":["Avoidance-avoidance","Approach-approach","Approach-avoidance"],"correct":0,"applyWhy":"Two undesirable alternatives create an avoidance-avoidance conflict."},{"id":"m043","topic":"u7t5","title":"Stress and coping","description":"Stress involves responses to demands, while coping refers to ways of managing those demands.","quick":"Stress involves responses to demands, while coping refers to ways of managing those demands.","core":"The NET outline includes stress models, Type A–D behaviors and strategies such as biofeedback, breathing, progressive muscular relaxation, mindfulness and stress inoculation training.","retrieve":"Which is a coping or stress-management strategy explicitly listed?","answer":"Progressive muscular relaxation.","applyQ":"A learner systematically tenses and relaxes muscle groups to reduce physiological tension. Which strategy is illustrated?","options":["Progressive muscular relaxation","Semantic differential","Social loafing"],"correct":0,"applyWhy":"Progressive muscular relaxation is explicitly listed as a stress-management strategy."},{"id":"m044","topic":"u8t1","title":"Social psychology: nature and scope","description":"Social psychology studies how people think about, influence and relate to one another.","quick":"Social psychology studies how people think about, influence and relate to one another.","core":"The supplied Unit 8 material defines social psychology around social influence and interpersonal relations and places it at psychology’s boundary with sociology.","retrieve":"What is the central focus of social psychology?","answer":"How people think about, influence and relate to one another.","applyQ":"A study examines how the presence of others changes an individual’s behavior. Which field is most directly relevant?","options":["Social psychology","Psychometrics","Physiological psychology"],"correct":0,"applyWhy":"The effect of social situations on individual behavior is central to social psychology."},{"id":"m045","topic":"u8t2","title":"Cognitive dissonance","description":"Cognitive dissonance concerns discomfort arising from inconsistency among cognitions or between beliefs and behavior.","quick":"Cognitive dissonance concerns discomfort arising from inconsistency among cognitions or between beliefs and behavior.","core":"The NET outline lists cognitive dissonance among traditional theoretical perspectives in social psychology.","retrieve":"What does cognitive dissonance involve?","answer":"Psychological tension arising from inconsistency among cognitions or behavior.","applyQ":"A person values health but repeatedly smokes and feels uncomfortable about the inconsistency. Which concept fits?","options":["Cognitive dissonance","Classical conditioning","Working memory"],"correct":0,"applyWhy":"The tension arises from inconsistency between a valued belief and behavior."},{"id":"m046","topic":"u8t3","title":"Attribution","description":"Attribution involves explaining the causes of behavior.","quick":"Attribution involves explaining the causes of behavior.","core":"The Unit 8 outline explicitly includes attributions within social perception.","retrieve":"What is attribution?","answer":"An explanation about the causes of behavior or events.","applyQ":"After a poor exam, a student explains the result by blaming lack of preparation. What process is this?","options":["Attribution","Operant reinforcement","Psychometric scaling"],"correct":0,"applyWhy":"The student is assigning a cause to an outcome."},{"id":"m047","topic":"u8t4","title":"Conformity, compliance and obedience","description":"Social influence can take different forms depending on the source and nature of the pressure.","quick":"Social influence can take different forms depending on the source and nature of the pressure.","core":"The NET outline lists conformity, peer pressure, persuasion, compliance and obedience as forms of social influence.","retrieve":"Which form of influence specifically concerns responding to an authority?","answer":"Obedience.","applyQ":"A person follows an instruction because it comes from an authority figure. Which process is most directly involved?","options":["Obedience","Conformity","Social loafing"],"correct":0,"applyWhy":"Obedience concerns behavior in response to authority."},{"id":"m048","topic":"u8t4","title":"Social loafing","description":"People may sometimes exert less individual effort when working collectively than when working alone.","quick":"People may sometimes exert less individual effort when working collectively than when working alone.","core":"The Unit 8 outline explicitly includes social loafing under group and social influence.","retrieve":"What is social loafing?","answer":"Reduced individual effort in a group task.","applyQ":"Each member of a group contributes less effort because individual contributions are difficult to identify. Which phenomenon fits?","options":["Social loafing","Social facilitation","Reactance"],"correct":0,"applyWhy":"Reduced individual effort in a group context is social loafing."},{"id":"m049","topic":"u8t5","title":"Social identity and intergroup relations","description":"Group membership can shape self-concept and relations between groups.","quick":"Group membership can shape self-concept and relations between groups.","core":"The NET outline includes Social Identity Theory, Minimal Group Experiment, Relative Deprivation Theory and Realistic Conflict Theory.","retrieve":"Which theory is explicitly included under intergroup relations?","answer":"Social Identity Theory.","applyQ":"A researcher examines how identifying with an in-group affects judgments of an out-group. Which theory is relevant?","options":["Social Identity Theory","Drive theory","Two-factor theory"],"correct":0,"applyWhy":"In-group and out-group identification is central to Social Identity Theory."},{"id":"m050","topic":"u8t6","title":"Applied social psychology","description":"Social psychology can be applied to health, environment, law and everyday social settings.","quick":"Social psychology can be applied to health, environment, law and everyday social settings.","core":"The supplied Unit 8 outline includes health, environment and law and topics such as personal space, crowding and territoriality.","retrieve":"Which area is explicitly listed as an application?","answer":"Health.","applyQ":"A psychologist uses social influence principles to improve adherence to a health behavior. Which applied area fits?","options":["Health","Psychophysics","Test construction"],"correct":0,"applyWhy":"Health is explicitly identified as an applied social-psychology area."},{"id":"m051","topic":"u9t1","title":"Lifespan development","description":"Developmental psychology studies constancy and change across the lifespan.","quick":"Developmental psychology studies constancy and change across the lifespan.","core":"The supplied Unit 9 material describes lifespan development as the study of growth, change and adaptation across life stages.","retrieve":"What does lifespan development study?","answer":"Constancy and change throughout a person’s lifespan.","applyQ":"A researcher examines how people change from infancy through later adulthood. Which field is being used?","options":["Lifespan development","Psychometrics","Social influence"],"correct":0,"applyWhy":"The field examines change and continuity across the lifespan."},{"id":"m052","topic":"u9t1","title":"Developmental theories","description":"Developmental theories offer different explanations for how people grow and change.","quick":"Developmental theories offer different explanations for how people grow and change.","core":"The NET outline includes psychoanalytical, behavioristic and cognitive theories of development.","retrieve":"Which broad approaches are included in the Unit 9 outline?","answer":"Psychoanalytical, behavioristic and cognitive.","applyQ":"A syllabus compares Freud-inspired, learning-based and cognitive accounts of development. Which unit area is this?","options":["Developmental theories","Attitude scales","Social psychology"],"correct":0,"applyWhy":"Those three approaches are explicitly listed in the source."},{"id":"m053","topic":"u9t2","title":"Development across domains","description":"Development includes sensory-motor, cognitive, language, emotional, social and moral changes.","quick":"Development includes sensory-motor, cognitive, language, emotional, social and moral changes.","core":"The supplied Unit 9 outline lists these domains and also includes successful aging.","retrieve":"Which domain is explicitly listed in the source?","answer":"Moral development.","applyQ":"A researcher studies how judgments about right and wrong change across childhood and adolescence. Which domain is this?","options":["Moral development","Synaptic transmission","Attitude scaling"],"correct":0,"applyWhy":"Moral development is one of the listed developmental domains."},{"id":"m054","topic":"u9t3","title":"Psychopathology and mental status examination","description":"Psychopathology concerns patterns of psychological disturbance and their assessment.","quick":"Psychopathology concerns patterns of psychological disturbance and their assessment.","core":"The NET Unit 9 outline includes the concept of psychopathology, Mental Status Examination and classification.","retrieve":"What assessment procedure is explicitly listed under psychopathology?","answer":"Mental Status Examination.","applyQ":"A clinician systematically observes appearance, behavior, speech, mood, thought and related functioning during an assessment. What is this?","options":["Mental Status Examination","Likert scaling","Naturalistic observation"],"correct":0,"applyWhy":"The Mental Status Examination is explicitly included in the source."},{"id":"m055","topic":"u9t4","title":"Cognitive and behavioral therapies","description":"Psychotherapies use different mechanisms and techniques to address psychological problems.","quick":"Psychotherapies use different mechanisms and techniques to address psychological problems.","core":"The supplied sources include behavior therapy, REBT, CBT and other approaches; Ciccarelli/White distinguishes action therapies including behavior and cognitive therapies.","retrieve":"Which therapy is explicitly listed in the Unit 9 outline?","answer":"Cognitive Behavioral Therapy (CBT).","applyQ":"A therapist helps a client identify unhelpful thoughts and modify related behavior. Which approach fits?","options":["CBT","Semantic differential","Social loafing"],"correct":0,"applyWhy":"CBT combines cognitive and behavioral principles."},{"id":"m056","topic":"u9t4","title":"Person-centered therapy","description":"Person-centered therapy emphasizes the therapeutic relationship and the client’s capacity for growth.","quick":"Person-centered therapy emphasizes the therapeutic relationship and the client’s capacity for growth.","core":"Ciccarelli/White places humanistic therapy among insight therapies and the NET outline includes person-centered therapy.","retrieve":"Which broad tradition is associated with person-centered therapy?","answer":"Humanistic therapy.","applyQ":"A therapist emphasizes empathic understanding, acceptance and the client’s own direction of change. Which tradition fits?","options":["Humanistic/person-centered","Operant conditioning","Psychometric testing"],"correct":0,"applyWhy":"These are central features of the person-centered approach."},{"id":"m057","topic":"u9t6","title":"Guidance and counselling in schools","description":"Guidance and counselling support educational, personal and developmental needs.","quick":"Guidance and counselling support educational, personal and developmental needs.","core":"The NET outline includes needs, organizational setup and techniques for school guidance and counselling process, skills and techniques.","retrieve":"Which area is explicitly included under school guidance?","answer":"Needs and organizational setup.","applyQ":"A school develops a structured service to help students with educational and personal concerns. Which Unit 9 area does this represent?","options":["Guidance and counselling","Experimental design","Attitude scaling"],"correct":0,"applyWhy":"School guidance and counselling are explicitly included in the source."},{"id":"m058","topic":"u10t1","title":"Social issues and psychology","description":"Psychology can contribute to understanding and addressing social problems through theory and applied work.","quick":"Psychology can contribute to understanding and addressing social problems through theory and applied work.","core":"The supplied Unit 10 material defines social problems using objective and subjective components and discusses psychology’s role in understanding social issues.","retrieve":"Why can psychology be relevant to social problems?","answer":"It can apply psychological concepts to understand and influence behavior in social contexts.","applyQ":"A program uses social-psychological principles to address a community behavior problem. What role of psychology is illustrated?","options":["Applied social psychology","Psychometric norming","Sensory transduction"],"correct":0,"applyWhy":"The source emphasizes applying psychological theory to societal problems."},{"id":"m059","topic":"u10t2","title":"Gender, stigma and marginalization","description":"Social issues include cultural bias, discrimination, stigma, marginalization and social suffering.","quick":"Social issues include cultural bias, discrimination, stigma, marginalization and social suffering.","core":"The Unit 10 outline explicitly lists gender, poverty, disability and migration and associated issues such as stigma and discrimination.","retrieve":"Which issue is explicitly listed under Unit 10?","answer":"Stigma.","applyQ":"A group is excluded and negatively labelled because of a socially disapproved characteristic. Which concept is relevant?","options":["Stigma and marginalization","Spontaneous recovery","Chunking"],"correct":0,"applyWhy":"Stigma and marginalization are explicitly included in the Unit 10 outline."},{"id":"m060","topic":"u10t3","title":"Peace psychology","description":"Peace psychology examines psychological dimensions of violence, non-violence and conflict resolution.","quick":"Peace psychology examines psychological dimensions of violence, non-violence and conflict resolution.","core":"The supplied outline includes violence, non-violence, conflict resolution at macro level and the role of media in conflict resolution.","retrieve":"Which topic belongs to peace psychology in the source?","answer":"Conflict resolution.","applyQ":"A program examines how communication and media can reduce escalation between groups. Which area fits?","options":["Peace psychology","Psychometrics","Operant conditioning"],"correct":0,"applyWhy":"Conflict resolution and media are explicitly listed in this area."},{"id":"m061","topic":"u10t4","title":"Hedonic and eudemonic wellbeing","description":"Wellbeing can be approached through pleasure and positive experience as well as meaning and functioning.","quick":"Wellbeing can be approached through pleasure and positive experience as well as meaning and functioning.","core":"The Unit 10 outline explicitly identifies hedonic and eudemonic wellbeing, character strengths, resilience and post-traumatic growth.","retrieve":"Which two types of wellbeing are listed?","answer":"Hedonic and eudemonic.","applyQ":"A framework distinguishes feeling good from living meaningfully and functioning well. Which distinction is this?","options":["Hedonic vs eudemonic wellbeing","Approach vs avoidance conflict","Reliability vs validity"],"correct":0,"applyWhy":"The supplied outline uses the hedonic/eudemonic distinction."},{"id":"m062","topic":"u10t5","title":"Health and health behavior","description":"Psychology studies behaviors that promote or compromise health and the psychological processes linked with illness.","quick":"Psychology studies behaviors that promote or compromise health and the psychological processes linked with illness.","core":"The Unit 10 outline includes health-promoting and health-compromising behaviors, lifestyle and chronic diseases, and psychoneuroimmunology.","retrieve":"Which is a health topic explicitly included in Unit 10?","answer":"Health-promoting behavior.","applyQ":"A psychologist designs an intervention to increase physical activity and improve adherence to treatment. Which area fits?","options":["Health psychology","Test construction","Social loafing"],"correct":0,"applyWhy":"Health-promoting behavior and lifestyle are explicitly included."},{"id":"m063","topic":"u10t6","title":"Psychology and digital technology","description":"Digital environments create new contexts for learning, social interaction, risk and parenting.","quick":"Digital environments create new contexts for learning, social interaction, risk and parenting.","core":"The Unit 10 outline includes digital learning, digital etiquette, cyberbullying, cyber pornography and parental mediation of digital usage.","retrieve":"Which digital-world topic is explicitly listed?","answer":"Cyberbullying.","applyQ":"A school program teaches students how to respond to harmful peer behavior occurring through digital platforms. Which topic is most directly relevant?","options":["Cyberbullying","Psychometric reliability","Classical conditioning"],"correct":0,"applyWhy":"Cyberbullying is explicitly listed in the psychology-and-technology section."},{"id":"m064","topic":"u4t4","title":"Methods of Physiological Psychology","description":"Physiological psychology uses invasive and non-invasive methods to study biological mechanisms of behavior.","quick":"The Unit 4 source distinguishes invasive anatomical, lesion, chemical and microelectrode methods from non-invasive EEG and scanning methods.","core":"The supplied NET outline groups anatomical methods, degeneration techniques, lesion techniques, chemical methods and microelectrode studies as invasive approaches, while EEG and scanning methods are listed as non-invasive.","retrieve":"Name one non-invasive method listed in the Unit 4 outline.","answer":"EEG or a scanning method.","applyQ":"A researcher records electrical activity from the scalp without surgically altering brain tissue. Which method fits?","options":["EEG","Lesion technique","Chemical method"],"correct":0,"applyWhy":"EEG is explicitly listed as a non-invasive physiological method."},{"id":"m065","topic":"u9t5","title":"Applications of Learning and Motivation in Education","description":"Psychological principles can be applied to educational achievement and teacher effectiveness.","quick":"The Unit 9 outline applies theories of motivation and learning to school settings and educational achievement.","core":"The supplied source includes applications of theories of motivation and learning in school, factors in educational achievement, and teacher effectiveness.","retrieve":"Which two psychological areas are explicitly applied in school settings in the Unit 9 outline?","answer":"Motivation and learning.","applyQ":"A teacher redesigns classroom consequences and goal-setting to increase student engagement. Which Unit 9 area is being applied?","options":["Applications of motivation and learning","Psychological testing history","Peace psychology"],"correct":0,"applyWhy":"The Unit 9 outline explicitly includes applications of motivation and learning in school."}],"mcqs":[{"id":"q-m001","type":"MCQ","microtopic":"m001","question":"A researcher first records a pattern, then proposes why it occurs, forecasts when it may occur, and designs an intervention. Which sequence of goals is represented?","options":["Describe → explain → predict → control","Measure → diagnose → prescribe → treat","Observe → remember → forget → generalize"],"answer":0,"explanation":"The sequence matches the four goals identified in the supplied source."},{"id":"q-m002","type":"MCQ","microtopic":"m002","question":"A psychologist deliberately limits explanations to observable responses and environmental conditions. Which school is most closely represented?","options":["Behaviorism","Structuralism","Gestalt psychology"],"answer":0,"explanation":"The emphasis on observable behavior is characteristic of behaviorism."},{"id":"q-m003","type":"MCQ","microtopic":"m003","question":"A researcher studies attention, memory and thinking using information-processing models. Which broad development does this reflect?","options":["Cognitive revolution","Classical conditioning","Psychometric standardization"],"answer":0,"explanation":"Attention, memory and thinking are central examples of cognitive processes."},{"id":"q-m004","type":"MCQ","microtopic":"m004","question":"A course describes psychology as the study of the person rather than only isolated behavior. Which term from the source fits?","options":["Jiva","Synapse","Norm"],"answer":0,"explanation":"The cited classical Indian formulation uses Jiva for the person."},{"id":"q-m005","type":"MCQ","microtopic":"m005","question":"A researcher separately asks what reality is, how it can be known, and which procedures should be used. What framework is being applied?","options":["Ontology, epistemology, methodology","Reliability, validity, norms","Stimulus, response, reinforcement"],"answer":0,"explanation":"These three terms map directly onto the three questions in the scenario."},{"id":"q-m006","type":"MCQ","microtopic":"m006","question":"A researcher predicts that sleep duration will be associated with memory performance and then collects data. What is the prediction?","options":["A hypothesis","A norm","A sampling frame"],"answer":0,"explanation":"A testable prediction about variables is a hypothesis."},{"id":"q-m007","type":"MCQ","microtopic":"m007","question":"A psychologist observes children on a playground without assigning conditions or manipulating variables. Which method is this?","options":["Naturalistic observation","Laboratory experiment","Randomized trial"],"answer":0,"explanation":"The defining feature here is observation in a natural setting without experimental manipulation."},{"id":"q-m008","type":"MCQ","microtopic":"m008","question":"A researcher assigns participants to two study schedules and measures test scores. Which is the independent variable?","options":["Study schedule","Test score","Population"],"answer":0,"explanation":"The study schedule is the manipulated condition."},{"id":"q-m009","type":"MCQ","microtopic":"m009","question":"A researcher examines how meanings are produced through social interaction and language. Which listed paradigm is especially relevant?","options":["Social constructionism","Classical conditioning","Trait theory"],"answer":0,"explanation":"The supplied outline explicitly includes social constructionism."},{"id":"q-m010","type":"MCQ","microtopic":"m010","question":"As study time increases, test scores tend to increase in a sample. What association is suggested?","options":["Positive correlation","Negative correlation","Zero correlation"],"answer":0,"explanation":"Both variables move in the same direction."},{"id":"q-m011","type":"MCQ","microtopic":"m011","question":"Two groups are treated alike except for one experimental condition. What is the purpose?","options":["To isolate the treatment effect","To eliminate measurement entirely","To replace the hypothesis"],"answer":0,"explanation":"Keeping other conditions comparable strengthens causal inference."},{"id":"q-m012","type":"MCQ","microtopic":"m012","question":"A standardized instrument is administered, scored and interpreted to infer an attribute. What activity is being described?","options":["Psychological testing","Naturalistic observation","Free association"],"answer":0,"explanation":"This matches the supplied definition of psychological testing."},{"id":"q-m013","type":"MCQ","microtopic":"m013","question":"A test developer reviews whether individual questions function appropriately before finalizing a scale. Which area is involved?","options":["Item analysis","Random assignment","Dream analysis"],"answer":0,"explanation":"Evaluating individual items is item analysis."},{"id":"q-m014","type":"MCQ","microtopic":"m014","question":"A test gives consistent scores but its scores do not support the intended interpretation. Which issue needs closer examination?","options":["Validity","Reliability alone","Sampling only"],"answer":0,"explanation":"Consistency and validity are distinct; intended interpretation concerns validity."},{"id":"q-m015","type":"MCQ","microtopic":"m015","question":"An assessment estimates a person’s potential to learn a particular skill. Which area is most relevant?","options":["Aptitude testing","Attitude scaling","Crowding"],"answer":0,"explanation":"Aptitude concerns potential or capacity relevant to learning or performance."},{"id":"q-m016","type":"MCQ","microtopic":"m016","question":"Respondents indicate their level of agreement with a series of statements. Which format fits best?","options":["Likert scale","Naturalistic observation","Sociogram"],"answer":0,"explanation":"Agreement ratings are characteristic of Likert-type scales."},{"id":"q-m017","type":"MCQ","microtopic":"m017","question":"A researcher investigates how neural activity relates to behavior. Which broad field is being used?","options":["Biopsychology","Psychometrics","Social constructionism"],"answer":0,"explanation":"The research question directly concerns biological mechanisms of behavior."},{"id":"q-m018","type":"MCQ","microtopic":"m018","question":"A specialized receptor responds to a particular type of physical energy. What process is being described?","options":["Sensory reception","Norming","Extinction"],"answer":0,"explanation":"Receptors transduce or detect particular forms of stimulation."},{"id":"q-m019","type":"MCQ","microtopic":"m019","question":"A cell receives information and transmits a neural signal to other cells. What is it?","options":["Neuron","Endocrine gland","Psychological test"],"answer":0,"explanation":"Neurons are the basic communicating cells of the nervous system."},{"id":"q-m020","type":"MCQ","microtopic":"m020","question":"A chemical messenger released from one neuron affects the next cell. Which concept is involved?","options":["Neurotransmitter-mediated synaptic transmission","Norm referencing","Classical extinction"],"answer":0,"explanation":"Neurotransmitters participate in chemical communication across synapses."},{"id":"q-m021","type":"MCQ","microtopic":"m021","question":"Researchers compare twins and adopted individuals to separate hereditary and environmental influences. What issue is being studied?","options":["Nature–nurture","Attitude scaling","Social loafing"],"answer":0,"explanation":"Twin and adoption studies are classic ways to examine hereditary and environmental contributions."},{"id":"q-m022","type":"MCQ","microtopic":"m022","question":"In a noisy room, a student concentrates on one conversation while ignoring most background talk. What is illustrated?","options":["Selective attention","Retroactive interference","Projection"],"answer":0,"explanation":"The learner selects one information stream for focused processing."},{"id":"q-m023","type":"MCQ","microtopic":"m023","question":"Two people receive similar sensory input but organize it differently because of context. Which process is central?","options":["Perception","Synaptic transmission","Norming"],"answer":0,"explanation":"Perception involves interpretation and organization of sensory information."},{"id":"q-m024","type":"MCQ","microtopic":"m024","question":"A straight line is seen as bent because of surrounding visual context. Which phenomenon fits?","options":["Illusion","Hallucination","Amnesia"],"answer":0,"explanation":"There is a real stimulus, but it is interpreted incorrectly."},{"id":"q-m025","type":"MCQ","microtopic":"m025","question":"A clinic becomes anxiety-provoking after repeated pairing with painful treatment. What learning process is illustrated?","options":["Classical conditioning","Operant conditioning","Insight learning"],"answer":0,"explanation":"The clinic acquires an eliciting function through association."},{"id":"q-m026","type":"MCQ","microtopic":"m026","question":"A student receives praise after completing practice questions and completes more questions later. What consequence is operating?","options":["Reinforcement","Punishment","Extinction"],"answer":0,"explanation":"A consequence that increases future behavior is reinforcement."},{"id":"q-m027","type":"MCQ","microtopic":"m027","question":"A child learns a new action after watching an older sibling perform it. What learning process is illustrated?","options":["Observational learning","Classical extinction","Retrograde amnesia"],"answer":0,"explanation":"The behavior is acquired through observation of a model."},{"id":"q-m028","type":"MCQ","microtopic":"m028","question":"A learner takes information in, retains it, and later brings it back to mind. Which sequence is this?","options":["Encoding → storage → retrieval","Stimulus → response → punishment","Sensation → receptor → hormone"],"answer":0,"explanation":"These are the standard memory processes highlighted in the source."},{"id":"q-m029","type":"MCQ","microtopic":"m029","question":"After a brain injury, a person can discuss old events but cannot reliably form new memories. Which pattern fits?","options":["Anterograde amnesia","Retrograde amnesia","Selective attention"],"answer":0,"explanation":"The difficulty is specifically with forming new memories."},{"id":"q-m030","type":"MCQ","microtopic":"m030","question":"A learner suddenly reorganizes a problem and sees the relationship among its parts as a whole. Which perspective fits?","options":["Gestalt","Behaviorism","Psychometric theory"],"answer":0,"explanation":"Gestalt emphasizes organized wholes and restructuring of experience."},{"id":"q-m031","type":"MCQ","microtopic":"m031","question":"A student groups different examples under the category “reinforcer” despite their different physical forms. What process is involved?","options":["Concept formation","Synaptic transmission","Norming"],"answer":0,"explanation":"The student is organizing varied instances under a common category."},{"id":"q-m032","type":"MCQ","microtopic":"m032","question":"A learner uses a general rule and a specific case to reach a conclusion. Which process is involved?","options":["Reasoning","Classical conditioning","Attitude scaling"],"answer":0,"explanation":"The learner is deriving a conclusion from available information."},{"id":"q-m033","type":"MCQ","microtopic":"m033","question":"A student knows the desired result but cannot see how to reach it and tries several strategies. What process is central?","options":["Problem solving","Simple recall","Psychological testing"],"answer":0,"explanation":"The central feature is a goal with an initially unavailable route."},{"id":"q-m034","type":"MCQ","microtopic":"m034","question":"A student notices that rereading is not helping and changes strategy to self-testing. What is this an example of?","options":["Metacognitive regulation","Classical conditioning","Social loafing"],"answer":0,"explanation":"The student monitors cognition and changes strategy accordingly."},{"id":"q-m035","type":"MCQ","microtopic":"m035","question":"A theory proposes a general factor contributing to performance across different cognitive tasks. Whose model is most directly represented?","options":["Spearman","Guilford","Torrance"],"answer":0,"explanation":"Spearman proposed a general intelligence factor, g."},{"id":"q-m036","type":"MCQ","microtopic":"m036","question":"A researcher measures divergent production and creative responses in students. Which Unit 6 area is being assessed?","options":["Creativity","Classical conditioning","Norms"],"answer":0,"explanation":"Divergent production and creative responses belong to the creativity area."},{"id":"q-m037","type":"MCQ","microtopic":"m037","question":"A researcher explains stable individual differences using dimensions that vary across people. Which approach is this?","options":["Trait approach","Behavioral economics","Psychophysics"],"answer":0,"explanation":"Trait approaches describe relatively enduring dimensions of individual differences."},{"id":"q-m038","type":"MCQ","microtopic":"m038","question":"A person generally believes outcomes depend mainly on their own actions. Which construct is relevant?","options":["Locus of control","Conditioned stimulus","Normative influence"],"answer":0,"explanation":"The scenario concerns beliefs about personal control over outcomes."},{"id":"q-m039","type":"MCQ","microtopic":"m039","question":"A state of internal tension energizes behavior toward a goal. Which motivational concept fits?","options":["Drive","Norm","Illusion"],"answer":0,"explanation":"Drive refers to an energizing state associated with a need."},{"id":"q-m040","type":"MCQ","microtopic":"m040","question":"A student is strongly motivated by meeting challenging standards of performance. Which motive is especially relevant?","options":["Achievement","Affiliation","Territoriality"],"answer":0,"explanation":"Concern with challenging standards and accomplishment is achievement motivation."},{"id":"q-m041","type":"MCQ","microtopic":"m041","question":"A theory proposes that bodily changes contribute to the experience of emotion rather than merely following it. Which theory is being referenced?","options":["James–Lange","Trait theory","Social identity theory"],"answer":0,"explanation":"James–Lange places bodily responses before the conscious emotional experience."},{"id":"q-m042","type":"MCQ","microtopic":"m042","question":"A person must choose between two unpleasant options and wants to escape both. What type is this?","options":["Avoidance-avoidance","Approach-approach","Approach-avoidance"],"answer":0,"explanation":"Two undesirable alternatives create an avoidance-avoidance conflict."},{"id":"q-m043","type":"MCQ","microtopic":"m043","question":"A learner systematically tenses and relaxes muscle groups to reduce physiological tension. Which strategy is illustrated?","options":["Progressive muscular relaxation","Semantic differential","Social loafing"],"answer":0,"explanation":"Progressive muscular relaxation is explicitly listed as a stress-management strategy."},{"id":"q-m044","type":"MCQ","microtopic":"m044","question":"A study examines how the presence of others changes an individual’s behavior. Which field is most directly relevant?","options":["Social psychology","Psychometrics","Physiological psychology"],"answer":0,"explanation":"The effect of social situations on individual behavior is central to social psychology."},{"id":"q-m045","type":"MCQ","microtopic":"m045","question":"A person values health but repeatedly smokes and feels uncomfortable about the inconsistency. Which concept fits?","options":["Cognitive dissonance","Classical conditioning","Working memory"],"answer":0,"explanation":"The tension arises from inconsistency between a valued belief and behavior."},{"id":"q-m046","type":"MCQ","microtopic":"m046","question":"After a poor exam, a student explains the result by blaming lack of preparation. What process is this?","options":["Attribution","Operant reinforcement","Psychometric scaling"],"answer":0,"explanation":"The student is assigning a cause to an outcome."},{"id":"q-m047","type":"MCQ","microtopic":"m047","question":"A person follows an instruction because it comes from an authority figure. Which process is most directly involved?","options":["Obedience","Conformity","Social loafing"],"answer":0,"explanation":"Obedience concerns behavior in response to authority."},{"id":"q-m048","type":"MCQ","microtopic":"m048","question":"Each member of a group contributes less effort because individual contributions are difficult to identify. Which phenomenon fits?","options":["Social loafing","Social facilitation","Reactance"],"answer":0,"explanation":"Reduced individual effort in a group context is social loafing."},{"id":"q-m049","type":"MCQ","microtopic":"m049","question":"A researcher examines how identifying with an in-group affects judgments of an out-group. Which theory is relevant?","options":["Social Identity Theory","Drive theory","Two-factor theory"],"answer":0,"explanation":"In-group and out-group identification is central to Social Identity Theory."},{"id":"q-m050","type":"MCQ","microtopic":"m050","question":"A psychologist uses social influence principles to improve adherence to a health behavior. Which applied area fits?","options":["Health","Psychophysics","Test construction"],"answer":0,"explanation":"Health is explicitly identified as an applied social-psychology area."},{"id":"q-m051","type":"MCQ","microtopic":"m051","question":"A researcher examines how people change from infancy through later adulthood. Which field is being used?","options":["Lifespan development","Psychometrics","Social influence"],"answer":0,"explanation":"The field examines change and continuity across the lifespan."},{"id":"q-m052","type":"MCQ","microtopic":"m052","question":"A syllabus compares Freud-inspired, learning-based and cognitive accounts of development. Which unit area is this?","options":["Developmental theories","Attitude scales","Social psychology"],"answer":0,"explanation":"Those three approaches are explicitly listed in the source."},{"id":"q-m053","type":"MCQ","microtopic":"m053","question":"A researcher studies how judgments about right and wrong change across childhood and adolescence. Which domain is this?","options":["Moral development","Synaptic transmission","Attitude scaling"],"answer":0,"explanation":"Moral development is one of the listed developmental domains."},{"id":"q-m054","type":"MCQ","microtopic":"m054","question":"A clinician systematically observes appearance, behavior, speech, mood, thought and related functioning during an assessment. What is this?","options":["Mental Status Examination","Likert scaling","Naturalistic observation"],"answer":0,"explanation":"The Mental Status Examination is explicitly included in the source."},{"id":"q-m055","type":"MCQ","microtopic":"m055","question":"A therapist helps a client identify unhelpful thoughts and modify related behavior. Which approach fits?","options":["CBT","Semantic differential","Social loafing"],"answer":0,"explanation":"CBT combines cognitive and behavioral principles."},{"id":"q-m056","type":"MCQ","microtopic":"m056","question":"A therapist emphasizes empathic understanding, acceptance and the client’s own direction of change. Which tradition fits?","options":["Humanistic/person-centered","Operant conditioning","Psychometric testing"],"answer":0,"explanation":"These are central features of the person-centered approach."},{"id":"q-m057","type":"MCQ","microtopic":"m057","question":"A school develops a structured service to help students with educational and personal concerns. Which Unit 9 area does this represent?","options":["Guidance and counselling","Experimental design","Attitude scaling"],"answer":0,"explanation":"School guidance and counselling are explicitly included in the source."},{"id":"q-m058","type":"MCQ","microtopic":"m058","question":"A program uses social-psychological principles to address a community behavior problem. What role of psychology is illustrated?","options":["Applied social psychology","Psychometric norming","Sensory transduction"],"answer":0,"explanation":"The source emphasizes applying psychological theory to societal problems."},{"id":"q-m059","type":"MCQ","microtopic":"m059","question":"A group is excluded and negatively labelled because of a socially disapproved characteristic. Which concept is relevant?","options":["Stigma and marginalization","Spontaneous recovery","Chunking"],"answer":0,"explanation":"Stigma and marginalization are explicitly included in the Unit 10 outline."},{"id":"q-m060","type":"MCQ","microtopic":"m060","question":"A program examines how communication and media can reduce escalation between groups. Which area fits?","options":["Peace psychology","Psychometrics","Operant conditioning"],"answer":0,"explanation":"Conflict resolution and media are explicitly listed in this area."},{"id":"q-m061","type":"MCQ","microtopic":"m061","question":"A framework distinguishes feeling good from living meaningfully and functioning well. Which distinction is this?","options":["Hedonic vs eudemonic wellbeing","Approach vs avoidance conflict","Reliability vs validity"],"answer":0,"explanation":"The supplied outline uses the hedonic/eudemonic distinction."},{"id":"q-m062","type":"MCQ","microtopic":"m062","question":"A psychologist designs an intervention to increase physical activity and improve adherence to treatment. Which area fits?","options":["Health psychology","Test construction","Social loafing"],"answer":0,"explanation":"Health-promoting behavior and lifestyle are explicitly included."},{"id":"q-m063","type":"MCQ","microtopic":"m063","question":"A school program teaches students how to respond to harmful peer behavior occurring through digital platforms. Which topic is most directly relevant?","options":["Cyberbullying","Psychometric reliability","Classical conditioning"],"answer":0,"explanation":"Cyberbullying is explicitly listed in the psychology-and-technology section."},{"id":"extra-01","type":"MCQ","microtopic":null,"question":"Which goal of scientific psychology concerns forecasting future behavior?","options":["Describe","Explain","Predict","Control"],"answer":2,"explanation":"Prediction concerns forecasting behavior or outcomes."},{"id":"extra-02","type":"MCQ","microtopic":null,"question":"Which research method is most directly associated with manipulation and control of variables?","options":["Experimental method","Naturalistic observation","Clinical case description","Historical analysis"],"answer":0,"explanation":"The experiment manipulates variables and provides control over conditions."},{"id":"extra-03","type":"MCQ","microtopic":null,"question":"Which psychometric concept concerns the consistency of measurement?","options":["Validity","Reliability","Norms","Utility"],"answer":1,"explanation":"Reliability concerns consistency or stability of measurement."},{"id":"extra-04","type":"MCQ","microtopic":null,"question":"Which structure carries information away from the neuron cell body?","options":["Dendrite","Axon","Soma membrane only","Receptor"],"answer":1,"explanation":"The axon conducts neural signals away from the cell body."},{"id":"extra-05","type":"MCQ","microtopic":null,"question":"Which process allows a neutral stimulus to become a conditioned stimulus?","options":["Association through conditioning","Random assignment","Norming","Factor analysis"],"answer":0,"explanation":"Conditioning establishes an association that gives the stimulus a learned eliciting function."},{"id":"extra-06","type":"MCQ","microtopic":null,"question":"Which memory problem primarily concerns inability to form new memories?","options":["Anterograde amnesia","Retrograde amnesia","Infantile amnesia only","Selective attention"],"answer":0,"explanation":"Anterograde amnesia concerns new learning after the onset of memory impairment."},{"id":"extra-07","type":"MCQ","microtopic":null,"question":"Which Unit 6 theorist is associated with multiple intelligences?","options":["Gardner","Spearman","Rotter","Pavlov"],"answer":0,"explanation":"Gardner proposed a theory of multiple intelligences."},{"id":"extra-08","type":"MCQ","microtopic":null,"question":"Which motive is most directly concerned with close relationships and belonging?","options":["Achievement","Affiliation","Power","Arousal"],"answer":1,"explanation":"Affiliation concerns relationships and social connection."},{"id":"extra-09","type":"MCQ","microtopic":null,"question":"Following an authority’s instruction is an example of:","options":["Conformity","Obedience","Social loafing","Reactance"],"answer":1,"explanation":"Obedience concerns behavior in response to authority."},{"id":"extra-10","type":"MCQ","microtopic":null,"question":"Which Unit 10 topic concerns recovery and growth following adversity?","options":["Post-traumatic growth","Psychometric scaling","Stimulus generalization","Test standardization"],"answer":0,"explanation":"Post-traumatic growth is explicitly listed under wellbeing and self-growth."},{"id":"q-m064","type":"MCQ","microtopic":"m064","question":"A researcher records electrical activity from the scalp without surgically altering brain tissue. Which method fits?","options":["EEG","Lesion technique","Chemical method"],"answer":0,"explanation":"EEG is explicitly listed as a non-invasive physiological method."},{"id":"q-m065","type":"MCQ","microtopic":"m065","question":"A teacher redesigns classroom consequences and goal-setting to increase student engagement. Which Unit 9 area is being applied?","options":["Applications of motivation and learning","Psychological testing history","Peace psychology"],"answer":0,"explanation":"The Unit 9 outline explicitly includes applications of motivation and learning in school."}],"pyqs":[],"sources":[{"name":"Psychology — A Self-Teaching Guide","role":"Foundational concepts, research methods, stress, personality, intelligence and introductory clinical material"},{"name":"Psychology by Ciccarelli & White, 6th Edition","role":"Core learning, cognition, memory, learning, personality, psychological disorders and therapies"},{"name":"Baron & Misra","role":"Indian psychology and perspectives on mind, consciousness and psychological knowledge"},{"name":"NTA UGC NET/JRF/SLET Psychology Paper 2 — PowerWithin","role":"NET/JRF/SET syllabus map and topic structure across all 10 units"}]};
